unt_per_item_unit,2)?></td><td><?=html_escape($r->notes??'—')?></td><?php if($can_manage):?><td class="text-nowrap"><a class="btn btn-outline-primary btn-sm" href="<?=site_url('unit-rates/'.$item->cost_item_id.'/allowance/'.$r->cost_item_resource_allowance_id.'/edit')?>">Edit</a> <a class="btn btn-outline-danger btn-sm" href="<?=site_url('unit-rates/'.$item->cost_item_id.'/allowance/'.$r->cost_item_resource_allowance_id.'/delete')?>">Delete</a></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></div></div></div></div>
